-- Civilopedia "Cecil Empire: Places". Original paraphrases of the novel; chapters in docs/pedia-draft.md.
INSERT
OR REPLACE INTO LocalizedText (Tag, LANGUAGE, Text)
VALUES
    ('LOC_PEDIA_CONCEPTS_PAGEGROUP_TSOD_CECIL_PLACES_NAME', 'zh_Hans_CN', '塞西尔帝国：地点'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_CITY_CHAPTER_CONTENT_TITLE', 'zh_Hans_CN', '塞西尔城'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_CITY_CHAPTER_CONTENT_PARA_1', 'zh_Hans_CN', '塞西尔公国（后来的塞西尔帝国）的首都，在南境的「不毛之地」上迅速崛起。清晨，魔能核心驱动的机械钟在最高的钟楼上奏响，魔导车沿环形大道穿过行政区与商人区。'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_CITY_CHAPTER_CONTENT_PARA_2', 'zh_Hans_CN', '初次到访的外国干员走进这座城时，往往要愣上很久：它先进得不可思议。'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_TANSAN_TOWN_CHAPTER_CONTENT_TITLE', 'zh_Hans_CN', '坦桑镇'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_TANSAN_TOWN_CHAPTER_CONTENT_PARA_1', 'zh_Hans_CN', '南境的小镇，莱斯利家族安德鲁子爵的领地，也是塞西尔开拓初期最近的补给点——菲利普和拜伦曾带人在这里采买粮食、工具、帐篷和药品。'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_TANSAN_TOWN_CHAPTER_CONTENT_PARA_2', 'zh_Hans_CN', '万物终亡会的教徒一度潜入镇中，用邪术控制了城堡里的人。高文·塞西尔公爵前来支援，铲除了盘踞在这里的邪教徒。'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_DARK_MOUNTAINS_CHAPTER_CONTENT_TITLE', 'zh_Hans_CN', '黑暗山脉'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_DARK_MOUNTAINS_CHAPTER_CONTENT_PARA_1', 'zh_Hans_CN', '横亘在南境尽头的巨大山脉。越靠近它，景色越荒凉，人类文明的痕迹也越来越淡。'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_DARK_MOUNTAINS_CHAPTER_CONTENT_PARA_2', 'zh_Hans_CN', '没有人想到，那位死而复生的开国英雄会选择这里作为重振家族的起点。新塞西尔领的开拓地，就建在黑暗山脉的北麓。'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_WHITEWATER_RIVER_CHAPTER_CONTENT_TITLE', 'zh_Hans_CN', '白水河'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_WHITEWATER_RIVER_CHAPTER_CONTENT_PARA_1', 'zh_Hans_CN', '流经新塞西尔领开拓地的河流，经运河支流与多尔贡河相连。从安苏王都出发的船，在多尔贡河上漂一个月，再转入白水河漂一周，才能抵达这片边陲之地。'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_WHITEWATER_RIVER_CHAPTER_CONTENT_PARA_2', 'zh_Hans_CN', '开拓地的第一座码头就修在白水河边。'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_SAINT_SUNIL_CHAPTER_CONTENT_TITLE', 'zh_Hans_CN', '圣苏尼尔'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_SAINT_SUNIL_CHAPTER_CONTENT_PARA_1', 'zh_Hans_CN', '安苏王国的古老王都，王室居于白银堡，城中还有圣光大教堂。南境与王都相隔千里，但塞西尔的眼线早已蛰伏在这座城里。');

INSERT
OR REPLACE INTO BaseGameText (Tag, Text)
VALUES
    ('LOC_PEDIA_CONCEPTS_PAGEGROUP_TSOD_CECIL_PLACES_NAME', 'Cecil Empire: Places'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_CITY_CHAPTER_CONTENT_TITLE', 'Cecil City'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_CITY_CHAPTER_CONTENT_PARA_1', 'Capital of the Duchy of Cecil, later the Cecil Empire, which rose with startling speed from the "barren lands" of the south. Each morning a mechanical clock driven by a mana core rings out from the tallest bell tower, and magitech cars travel the ring road through the administrative and merchant districts.'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_CITY_CHAPTER_CONTENT_PARA_2', 'Foreign agents seeing it for the first time often stand frozen for a long while: the city is advanced beyond belief.'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_TANSAN_TOWN_CHAPTER_CONTENT_TITLE', 'Tansan Town'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_TANSAN_TOWN_CHAPTER_CONTENT_PARA_1', 'A small town in the south, held by Viscount Andrew of House Leslie, and the nearest source of supplies in Cecil''s first days of settlement. Philip and Byron led parties here to buy grain, tools, tents and medicine.'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_TANSAN_TOWN_CHAPTER_CONTENT_PARA_2', 'Doomsday cultists once slipped into the town and used dark magic to control people inside the castle. Duke Gawain Cecil came to its aid and rooted them out.'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_DARK_MOUNTAINS_CHAPTER_CONTENT_TITLE', 'Dark Mountains'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_DARK_MOUNTAINS_CHAPTER_CONTENT_PARA_1', 'A vast range stretching across the far end of the south. The closer one comes, the bleaker the land, and the fainter the marks of human civilization.'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_DARK_MOUNTAINS_CHAPTER_CONTENT_PARA_2', 'No one expected the resurrected founding hero to choose this place to restore his house. The new Cecil territory was settled on the northern slopes of the Dark Mountains.'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_WHITEWATER_RIVER_CHAPTER_CONTENT_TITLE', 'Whitewater River'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_WHITEWATER_RIVER_CHAPTER_CONTENT_PARA_1', 'The river that flows past the new Cecil territory, joined to the Dorgon River by a canal branch. A ship from the royal capital of Ansu drifted a month down the Dorgon and another week along the Whitewater before it reached this frontier.'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_WHITEWATER_RIVER_CHAPTER_CONTENT_PARA_2', 'The settlement''s first dock was built on the banks of the Whitewater.'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_SAINT_SUNIL_CHAPTER_CONTENT_TITLE', 'Saint Sunil'),
    ('LOC_PEDIA_CONCEPTS_PAGE_TSOD_CECIL_SAINT_SUNIL_CHAPTER_CONTENT_PARA_1', 'The ancient royal capital of the Kingdom of Ansu, where the royal family lived in Silver Castle beside the great Cathedral of the Holy Light. The south lay a thousand miles away, but Cecil''s informants had long been hidden inside the city.');
